commands.command:
/bin/bash -lc "cat > tests/specific_route_matching.test.mjs <<'EOF'
import test from \"node:test\";
import assert from \"node:assert/strict\";
import { matchRoute as domainMatch } from \"../src/specific_route_matching.ts\";
import { matchRoute as apiMatch } from \"../src/api.ts\";

for (const [name, match] of [[\"domain\", domainMatch], [\"api\", apiMatch]]) {
  test("'`${name}: selects the most literal match without changing route order`, () => {
    const routes = Object.freeze([
      Object.freeze({ id: "generic", pattern: "/:section/:id" }),
      Object.freeze({ id: "users", pattern: "/users/:id" }),
      Object.freeze({ id: "exact", pattern: "/users/new" }),
    ]);
    assert.equal(match(routes, "/users/new").id, "exact");
    const result = match(routes, "/users/alice");
    assert.equal(result.id, "users");
    assert.deepEqual({ ...result.params }, { id: "alice" });
    assert.deepEqual(routes.map(route => route.id), ["generic", "users", "exact"]);
  });

  test(`${name}: preserves input order for equal specificity`, () => {
    const result = match([
      { id: "first", pattern: "/:section/new" },
      { id: "second", pattern: "/users/:id" },
    ], "/users/new");
    assert.equal(result.id, "first");
    assert.deepEqual({ ...result.params }, { section: "users" });
  });

  test(`${name}: decodes request segments exactly once, including literals`, () => {
    assert.equal(match([{ id: "literal", pattern: "/café" }], "/caf%C3%A9").id, "literal");
    const routes = [{ id: "param", pattern: "/users/:id" }];
    for (const [encoded, decoded] of [["%252F", "%2F"], ["%255C", "%5C"], ["%25", "%"], ["a%20b", "a b"]]) {
      assert.equal(match(routes, `/users/${encoded}`).params.id, decoded);
    }
    assert.equal(match([{ id: "literal", pattern: "/%2F" }], "/%252F").id, "literal");
  });

  test(`${name}: rejects malformed escapes and decoded separators`, () => {
    for (const path of ["/%", "/%GG", "/%C3%28", "/%2f", "/%5c", "/a%2Fb", "/a'"\\\\b\"]) {
      assert.throws(() => match([{ id: \"param\", pattern: \"/:value\" }], path));
    }
  });

  test("'`${name}: requires equal segment counts`, () => {
    const routes = [{ id: "user", pattern: "/users/:id" }];
    for (const path of ["/users", "/users/a/extra", "/users/a/", "users/a", "/other/a"]) {
      assert.equal(match(routes, path), null);
    }
    assert.equal(match([], "/users/a"), null);
    assert.equal(match([{ id: "root", pattern: "/" }], "/").id, "root");
  });
}
EOF
node --test tests/*.test.mjs'
